mapper.select:
SELECT TTT1.* FROM ( SELECT SRVC_PVSN_RQST_NO , RESRCE_NO , RQST_UNT_TASKWK_SE_CD , RQST_UNT_TASKWK_SE_NM , RCPT_RQST_COURS_SE_CD , RCPT_RQST_COURS_SE_NM , RQST_YMD , CLINT_NO , CLINT_NM , RQST_CS_CN , PRNMNT_USE_BGNG_YMD , PRNMNT_USE_BGNG_HR , PRNMNT_USE_END_YMD , PRNMNT_USE_END_HR , RCPT_UNT_TASKWK_SE_CD , RCPT_UNT_TASKWK_SE_NM , CLR_NO , CLR_NM , RCPT_INST_NO , RCPT_INST_NM , RQST_TRPR_INFO_NO , RQST_TRPR_INFO_NM , INDV_IDNTFC_NO , RQST_APLY_YN , RQST_DTL_CN , LINK_TYPE_SE_CD , LINK_TYPE_SE_NM , ATFINO , TRMN_PRCS_YN , RQST_INST_NO , RQST_INST_NM , RCPT_SE_CD , RCPT_TRPR_INFO_NO , RCPT_DTL_CN , RCPT_YMD , RRQST_RCPT_INST_NO , FIRST_RCPT_YMD , CASE_TRPR_NOAP_CS_SE_CD , CASE_MNG_SE_CD , STU_AGRE_STS_CD , STTY_AGT_AGRE_STS_CD , CASE_PRGRS_STTS_SE_CD , ESB_SEQ , PRVC_PVSN_AGRE_YN , ROWNUM AS SEQ
) TTT1
WHERE TTT1.SEQ >= #{START_IDX} AND TTT1.SEQ <= #{LAST_IDX}

mapper.sql:
        WHERE 1=1


	            AND 1=1


	            AND ((TT1.RCPT_INST_NO IN

		            #{item}

		        ) or (TT1.RRQST_RCPT_INST_NO IN

		            #{item}

		        ))

		            /*종사자*/
		            AND ((TT1.CLR_NO IS NULL OR TT1.CLR_NO = '0') OR (TT1.CLR_NO IS NOT NULL AND TT1.CLR_NO = #{ENFSN_NO}))





            AND TT1.RQST_TRPR_INFO_NM = #{RQST_TRPR_INFO_NM} 




            AND TT1.CLINT_NO LIKE '%' || #{CLINT_NO} || '%'




            AND TT1.CLINT_NM = #{CLINT_NM} 




            AND TT1.RQST_INST_NO LIKE '%' || #{RQST_INST_NO} || '%'




            AND TT1.RQST_INST_NM LIKE '%' || #{RQST_INST_NM} || '%'




            AND TT1.RCPT_INST_NO LIKE '%' || #{RCPT_INST_NO} || '%'




            AND TT1.RCPT_INST_NM LIKE '%' || #{RCPT_INST_NM} || '%'




            AND TT1.RCPT_SE_CD = #{RCPT_SE_CD}




            AND TT1.RQST_YMD BETWEEN #{PRNMNT_USE_BGNG_YMD} AND #{PRNMNT_USE_END_YMD}




            AND TT1.RCPT_YMD = #{RCPT_YMD}




           AND TT1.CASE_PRGRS_STTS_SE_CD IN (SELECT CMMNS_CD_VALUE FROM SAC100
                                             WHERE CMMNS_CD_ID       = 'CASE_PRGRS_STTS_SE_CD'
                                               AND UP_CMMNS_CD_VALUE = #{CASE_PRGRS_STTS_TYPE_SE_CD})



           AND TT1.CASE_PRGRS_STTS_SE_CD = #{CASE_PRGRS_STTS_SE_CD}



            AND TT1.CASE_TRPR_NOAP_CS_SE_CD = #{CASE_TRPR_NOAP_CS_SE_CD}




            AND TT1.CASE_MNG_SE_CD = #{CASE_MNG_SE_CD}




            AND TT1.STU_AGRE_STS_CD = #{STU_AGRE_STS_CD}




            AND TT1.STTY_AGT_AGRE_STS_CD = #{STTY_AGT_AGRE_STS_CD}




            AND (TO_CHAR(TO_DATE(TT1.RQST_YMD) + 13, 'YYYYMMDD') < TO_CHAR(SYSDATE, 'YYYYMMDD') AND TT1.RCPT_SE_CD = '11')
